            strXml += '    <c:showSerName val="' + (opts.showSerName ? "1" : "0") + '"/>';
            strXml += '    <c:showPercent val="' + (opts.showPercent ? "1" : "0") + '"/>';
            strXml += '    <c:showBubbleSize val="0"/>';
