      strXml += '  <c:scaling><c:orientation val="' + (opts.serAxisOrientation || (opts.barDir === "col" ? "minMax" : "minMax")) + '"/></c:scaling>';
      strXml += '  <c:delete val="' + (opts.serAxisHidden ? "1" : "0") + '"/>';
      strXml += '  <c:axPos val="' + (opts.barDir === "col" ? "b" : "l") + '"/>';
